import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称","description":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","frontmatter":{"title":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称","description":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","splitFrom":"life/personal/yijing/hexagrams-17-24.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读三：随蛊临观至噬嗑贲剥复","summary":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 17 随：跟随之前先辨其正至19 临：接近众人，也预见盛势的限度","link":"/life/personal/yijing/hexagrams-17-24-part-01"},"next":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 23 剥：基础被侵蚀时先保其所依至读后比较与自测","link":"/life/personal/yijing/hexagrams-17-24-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 17 随：跟随之前先辨其正至19 临：接近众人，也预见盛势的限度","link":"/life/personal/yijing/hexagrams-17-24-part-01"},"next":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 23 剥：基础被侵蚀时先保其所依至读后比较与自测","link":"/life/personal/yijing/hexagrams-17-24-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-17-24-part-02.md","filePath":"life/personal/yijing/hexagrams-17-24-part-02.md"}'),o={name:"life/personal/yijing/hexagrams-17-24-part-02.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读三-随蛊临观至噬嗑贲剥复-·-20-观-观看他人-也让自己的行为可被检验至22-贲-文饰如何与真实相称" tabindex="-1">六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称 <a class="header-anchor" href="#六十四卦详读三-随蛊临观至噬嗑贲剥复-·-20-观-观看他人-也让自己的行为可被检验至22-贲-文饰如何与真实相称" aria-label="Permalink to &quot;六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-17-24">返回分篇目录</a></p><p>本组把注意力从个人进退转向关系如何形成、积弊如何修复、治理如何实施。随与蛊可比较顺从与整治，临与观可比较接近与审视，噬嗑与贲可比较强制裁断与文明表达，剥与复则讨论基础损耗和初步恢复。</p><p>本文实际对读维基文库《周易》各卦与《周易正义》卷三对应篇。引文为古籍文字，简体说明为本篇概括；用字有异处参考《正义》，例如噬嗑“臘肉”、剥“君子得輿”。《周易》单卦网页有时断句不同，剥卦辞按《正义》读为“不利有攸往”。这些整理不构成古本校勘结论，重要疑义另行标注。涉及日期、刑罚、王侯和祭祀时，应保留历史语境，不将其直接变成预测或今日行为规范。</p><h2 id="gua-20" tabindex="-1">20 观：观看他人，也让自己的行为可被检验 <a class="header-anchor" href="#gua-20" aria-label="Permalink to &quot;20 观：观看他人，也让自己的行为可被检验 {#gua-20}&quot;">​</a></h2><p><strong>卦符：䷓　上卦：巽 ☴（风）　下卦：坤 ☷（地）。观兼有观看与可供观仰的层次。</strong></p><p><strong>卦辞原文</strong>：觀：盥而不薦，有孚顒若。</p><p><strong>白话概括</strong>：卦辞借祭礼开始阶段的肃敬说明可观之道。盥涉及盥洗，王、孔注疏又联系灌祭解释；荐是进献祭品，顒若是庄敬貌。不能将它直接译成“只洗手不做事”，也不能抹去祭祀背景，只谈一般看风景。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：童觀，小人无咎，君子吝。</td><td>观看浅近，责任较小者尚可，有职责者如此便不足。小人与君子在此也涉及位置、责任，不宜只作人格辱骂。</td></tr><tr><td>六二：窺觀，利女貞。</td><td>从狭窄孔隙观看，视野受限。古代以闺内妇女的处境说明，此等级限制不应直接成为现代性别要求。</td></tr><tr><td>六三：觀我生，進退。</td><td>察看自身作为、处境或所生之效果，再决定进退。“生”有不同解释，不必锁定为生辰。</td></tr><tr><td>六四：觀國之光，利用賓于王。</td><td>观察国家的文物、制度与治理表现，可以参与王廷宾礼。应看实际秩序，不只看表面华丽。</td></tr><tr><td>九五：觀我生，君子无咎。</td><td>身在主位，检视自己的作为及影响；《小象》说观民，意味着不能只靠自我感觉评功。</td></tr><tr><td>上九：觀其生，君子无咎。</td><td>更超出个人占有地观察所生之事，仍须以君子之德为条件。其字所指有异说，不能假装只有一种现代翻译。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“風行地上，觀；先王以省方，觀民設教。”</p><p><strong>解释</strong>：巡省各地，观察民情，再安排教化。风遍地而行，提示观察范围应广；“观民”先于“设教”，也意味着措施需要对具体生活有所理解。</p><p><strong>整体读法与误区</strong>：全卦由童观、窥观到观国、观我、观其，视野与责任逐步改变。被观看者不能只经营外表，观看者也不能凭片段断全貌。与<a href="/life/personal/yijing/hexagrams-17-24-part-01#gua-19">临卦</a>对读，临侧重接近和容保，观侧重察看与示范；二者共同限制遥控式、自以为是的治理。</p><p><strong>细读线索</strong>：观与临上下翻转，阅读视角也由来到他人之前，转为观察自己与制度呈现什么。六三、九五都说观我生，所承担的范围却因位置而不同；九五的小象特意转向观民，提醒主政者须由民众处境反看自身。上九改我为其，又保留一层观察距离。把三个生字并读，比将它们统统理解成察看出生日期更能连上经传的自省与治理主题。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A7%80" target="_blank" rel="noopener noreferrer">《周易·观》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E8%A7%80" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·观》</a>。</p><h2 id="gua-21" tabindex="-1">21 噬嗑：除去阻隔，但裁断必须明慎 <a class="header-anchor" href="#gua-21" aria-label="Permalink to &quot;21 噬嗑：除去阻隔，但裁断必须明慎 {#gua-21}&quot;">​</a></h2><p><strong>卦符：䷔　上卦：离 ☲（火、电、明）　下卦：震 ☳（雷、动）。噬嗑读 shì hé。</strong></p><p><strong>卦辞原文</strong>：噬嗑：亨，利用獄。</p><p><strong>白话概括</strong>：口中有物，咬去阻隔才能合拢；《正义》以此说明刑法去除上下间的梗阻。这里的“狱”主要涉及讼狱、断案，不能只按监狱理解。全卦包含刑具和食物意象，呈现惩戒、审理的难度，不能直接拿来证明严刑越重越有效。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：屨校滅趾，无咎。</td><td>足上加刑具以限制行动，古注偏向在过恶初起时制止。校是木制刑具；灭趾的具体程度有不同理解。</td></tr><tr><td>六二：噬膚滅鼻，无咎。</td><td>咬柔软之肉而深入至鼻，象征审理对象虽较易处理，仍有制刚的力度。不能据象辞直接还原一种刑罚程序。</td></tr><tr><td>六三：噬臘肉，遇毒，小吝，无咎。</td><td>咬陈干之肉遇毒，表示处置遇到难题或反噬。经文有昔、腊等异文，不宜套成饮食卫生判断。</td></tr><tr><td>九四：噬乾胏，得金矢，利艱貞，吉。</td><td>带骨干肉更难咬，须坚定而有准则；金矢有刚直象征等解释，仍以艰难守正为条件。</td></tr><tr><td>六五：噬乾肉，得黃金，貞厲，无咎。</td><td>审理需居中，仍保持对危险的警觉。黄金在古注中可取中坚之义，不是发现金钱的预告。</td></tr><tr><td>上九：何校滅耳，凶。</td><td>负戴刑具而及耳，走到刑罚严重的阶段。“何”通荷；《小象》联系不听明告，突出积恶不改的后果。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“雷電噬嗑；先王以明罰敕法。”</p><p><strong>解释</strong>：雷取威动，电取照明；处罚应明确，法度应整饬。由明到断，不能只要威而不要明。古代法观念与现代程序、权利体系不同，本文不据此给出现代司法结论。</p><p><strong>整体读法与误区</strong>：初、上两爻偏向受刑者，中间各爻常被古注理解为用刑或治狱之人，读时不能把角色混为一谈。与下一卦贲的大象“无敢折狱”对照，可看到审理需要超出外观文饰的依据。咬除阻隔是比喻，不授权人把意见不同者直接视为需要清除的障碍。</p><p><strong>细读线索</strong>：噬嗑的食物由肤到腊肉、干胏、干肉，体现处理对象在软硬、阻隔上的差异；金矢、黄金又为判断加入刚直与居中的象征解释。它们不能直接还原成一份完整古代司法手册，因为爻辞是高度凝缩的比喻。初九与上九用刑具形成首尾，尤其适合追问同一人的过失何以由小累积为重。古传重视早止，但现代具体干预仍需要合比例和事实依据。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%99%AC%E5%97%91" target="_blank" rel="noopener noreferrer">《周易·噬嗑》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E5%99%AC%E5%97%91" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·噬嗑》</a>。</p><h2 id="gua-22" tabindex="-1">22 贲：文饰如何与真实相称 <a class="header-anchor" href="#gua-22" aria-label="Permalink to &quot;22 贲：文饰如何与真实相称 {#gua-22}&quot;">​</a></h2><p><strong>卦符：䷕　上卦：艮 ☶（山、止）　下卦：离 ☲（火、明）。贲读 bì，文饰之意。</strong></p><p><strong>卦辞原文</strong>：賁：亨，小利有攸往。</p><p><strong>白话概括</strong>：刚柔交错、彼此修饰，使事物具有可理解、可观赏的形式。《正义》明确以饰解释贲，但卦辞只说小利有攸往，提示形式不能承担全部事业。贲不是一概反对美，也不是鼓励包装遮丑，而是在文与质之间寻找相称关系。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：賁其趾，舍車而徒。</td><td>从自己的行步开始修饰，宁可舍车步行，也不接受不合宜的便利。外在体面应有正当来源。</td></tr><tr><td>六二：賁其須。</td><td>修饰胡须，依附于其所承的身体；古注借此说明文饰需要有实质所依，不能独立代替主体。</td></tr><tr><td>九三：賁如濡如，永貞吉。</td><td>文采润泽、相处融洽，仍须长久守正。美好的形式不能代替稳定品格。</td></tr><tr><td>六四：賁如皤如，白馬翰如，匪寇婚媾。</td><td>华饰与洁白交映，来者似可疑却可能为婚媾。皤是白，翰如关乎马的形态、行进，具体取象有异说。</td></tr><tr><td>六五：賁於丘園，束帛戔戔，吝，終吉。</td><td>丘园中的朴素礼物，虽显得薄少，最终仍吉。戋戋有少小、浅狭等解释，心意与合宜不全由排场衡量。</td></tr><tr><td>上九：白賁，无咎。</td><td>以素白为饰，到文饰之极而见朴素。白贲不是粗制滥造，而是去除不必要的浮华。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“山下有火，賁；君子以明庶政，无敢折獄。”</p><p><strong>解释</strong>：火照山下，可使日常政务清楚，却不可仅凭这种有限明察轻率断狱。折狱是裁断案件，涉及后果严重的事实判断，不能凭外观、修辞或体面来决定。</p><p><strong>整体读法与误区</strong>：贲从趾、须、濡润写到丘园与素白，说明美并不只有一条越来越华丽的路线。礼貌、仪式、文字与设计可以帮助表达，但当包装取代证据时就越过限度。与<a href="/life/personal/yijing/hexagrams-17-24-part-02#gua-21">噬嗑</a>相比，贲更适合讨论表达与教化；两卦的分工提醒我们把“看起来可信”与“已有充分依据”分开。</p><p><strong>细读线索</strong>：贲的六二只写须，须附着于颐，王、孔据此解释随上而兴；这种身体细节提醒文饰具有依附性。初九的徒步、六五的薄帛、上九的素白则共同降低豪华器物的重要。经文没有把文与质设置成非此即彼：有质无适当表达也未必便于相处，有饰而离质则更难长久。读者可选择一件日常礼仪，分别检视它表达了什么实情，又可能遮住什么事实。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B3%81" target="_blank" rel="noopener noreferrer">《周易·贲》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E8%B3%81" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·贲》</a>。</p>',34)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
